1	//! Chat input: a multi-line, Piton-highlighted editor on the left and a send
2	//! button on the right, in the body of the Code and Spec tabs. Enter adds a
3	//! line; Ctrl/Cmd+Enter sends, or queues the prompt while the harness works.
4	//! Tab cycles the tabs and Esc takes focus out of the input.
5	
6	use std::rc::Rc;
7	use std::sync::Arc;
8	
9	use gpui_kit::Focusable as _;
10	use gpui_kit::component::button::{Button, ButtonVariants};
11	use gpui_kit::component::input::{
12	    CompletionProvider, Editor, EditorState, Enter, Escape, IndentInline, InputEvent, Rope,
13	};
14	use gpui_kit::component::tab::{Tab, TabBar};
15	use gpui_kit::component::{ActiveTheme, Disableable};
16	use gpui_kit::*;
17	use lsp_types::{CompletionContext, CompletionResponse};
18	
19	use crate::harness_mentions;
20	use crate::main_window::FocusChat;
21	use crate::piton_lsp::PitonSession;
22	use crate::piton_syntax;
23	use crate::project_directory::ProjectDirectory;
24	use crate::project_lsp::ProjectLsp;
25	
26	/// The input grows with its text up to this many rows, then scrolls.
27	const MAX_ROWS: usize = 12;
28	
29	/// Room the editor keeps free at the right of each line when soft wrapping.
30	const WRAP_RIGHT_MARGIN: Pixels = px(10.);
31	
32	#[cfg(target_os = "macos")]
33	const SEND_SHORTCUT: &str = "⌘Enter";
34	#[cfg(not(target_os = "macos"))]
35	const SEND_SHORTCUT: &str = "Ctrl+Enter";
36	
37	/// The tabs the input sits in, in the order Tab cycles them.
38	const TABS: [SendMode; 2] = [SendMode::Code, SendMode::Spec];
39	
40	/// What a prompt is sent to work on: the selected tab.
41	#[derive(Clone, Copy, Debug, PartialEq)]
42	pub enum SendMode {
43	    Code,
44	    Spec,
45	}
46	
47	impl SendMode {
48	    fn label(self) -> &'static str {
49	        match self {
50	            SendMode::Code => "Code",
51	            SendMode::Spec => "Spec",
52	        }
53	    }
54	}
55	
56	/// Emitted with the input's text, and the mode it is sent in, when the user
57	/// sends it.
58	pub struct Submit {
59	    pub text: String,
60	    pub mode: SendMode,
61	}
62	
63	pub struct ChatInput {
64	    editor: Entity<EditorState>,
65	    /// The tab bar and its body, which Esc moves focus to: out of the input,
66	    /// but not onto nothing, where the window would hand it straight back.
67	    focus_handle: FocusHandle,
68	    /// Index into `TABS`.
69	    selected_tab: usize,
70	    lsp: Option<Arc<PitonSession>>,
71	    busy: bool,
72	    /// Width the editor's text was last laid out in, which decides where long
73	    /// lines soft wrap.
74	    text_width: Option<Pixels>,
75	    /// What the editor adds around its rows (padding and border) as last
76	    /// laid out, rounded to device pixels.
77	    chrome: Option<Pixels>,
78	    _subscriptions: Vec<Subscription>,
79	}
80	
81	impl EventEmitter<Submit> for ChatInput {}
82	
83	impl ChatInput {
84	    pub fn new(window: &mut Window, cx: &mut Context<Self>) -> Self {
85	        let editor = cx.new(|cx| {
86	            EditorState::new(window, cx)
87	                .language(piton_syntax::LANGUAGE_NAME)
88	                .line_number(false)
89	                .folding(false)
90	                .soft_wrap(true)
91	                // No empty rows below the last line: the input is sized to its
92	                // text, so any extra would be blank space, and it would leave
93	                // room for the editor to stay scrolled past the first line
94	                // after Enter grows the input.
95	                .scroll_beyond_last_line(Some(0))
96	                .placeholder(format!(
97	                    "Write a prompt… (/ for skills and commands, @ for agents, {SEND_SHORTCUT} to send)"
98	                ))
99	        });
100	        // Typing goes straight into the input, without clicking it first.
101	        editor.read(cx).focus_handle(cx).focus(window, cx);
102	
103	        let subscriptions = vec![
104	            cx.subscribe(&editor, |this, editor, event: &InputEvent, cx| {
105	                // An edit may be an accepted completion, whose import the
106	                // hidden anchor then takes on.
107	                if matches!(event, InputEvent::Change)
108	                    && let Some(lsp) = &this.lsp
109	                {
110	                    lsp.note_edit(&editor.read(cx).value());
111	                }
112	                // Re-render on every edit so the input can grow to fit its text.
113	                cx.notify();
114	            }),
115	            cx.observe_global_in::<ProjectLsp>(window, |this, _, cx| this.connect_lsp(cx)),
116	        ];
117	
118	        let mut this = Self {
119	            editor,
120	            focus_handle: cx.focus_handle(),
121	            selected_tab: 0,
122	            lsp: None,
123	            busy: false,
124	            text_width: None,
125	            chrome: None,
126	            _subscriptions: subscriptions,
127	        };
128	        this.connect_lsp(cx);
129	        this
130	    }
131	
132	    /// The project's `piton lsp` session, once it is running.
133	    pub fn lsp(&self) -> Option<Arc<PitonSession>> {
134	        self.lsp.clone()
135	    }
136	
137	    /// Moves keyboard focus into the input.
138	    pub fn focus(&mut self, window: &mut Window, cx: &mut Context<Self>) {
139	        self.editor.read(cx).focus_handle(cx).focus(window, cx);
140	    }
141	
142	    /// Inserts a harness mention at the cursor, after a space when the cursor
143	    /// follows other text, then moves focus into the input.
144	    pub fn insert_mention(&mut self, mention: &str, window: &mut Window, cx: &mut Context<Self>) {
145	        self.editor.update(cx, |editor, cx| {
146	            let value = editor.value();
147	            let follows_text = value
148	                .get(..editor.cursor())
149	                .and_then(|before| before.chars().next_back())
150	                .is_some_and(|c| !c.is_whitespace());
151	            let text = if follows_text {
152	                format!(" {mention}")
153	            } else {
154	                mention.to_string()
155	            };
156	            editor.insert(text, window, cx);
157	        });
158	        self.focus(window, cx);
159	    }
160	
161	    #[cfg(test)]
162	    pub fn value(&self, cx: &App) -> SharedString {
163	        self.editor.read(cx).value()
164	    }
165	
166	    #[cfg(test)]
167	    pub fn is_focused(&self, window: &Window, cx: &App) -> bool {
168	        self.editor.read(cx).focus_handle(cx).is_focused(window)
169	    }
170	
171	    /// Marks the harness as working; sending then queues the prompt.
172	    pub fn set_busy(&mut self, busy: bool, cx: &mut Context<Self>) {
173	        self.busy = busy;
174	        cx.notify();
175	    }
176	
177	    /// Points completions at the project's `piton lsp`, once it is running.
178	    /// Harness mentions complete without it.
179	    fn connect_lsp(&mut self, cx: &mut Context<Self>) {
180	        let client = ProjectLsp::get(cx);
181	        let connected = self.lsp.as_ref().map(|lsp| Arc::as_ptr(lsp.client()));
182	        if client.as_ref().map(Arc::as_ptr) == connected {
183	            return;
184	        }
185	        self.lsp = client.map(|client| Arc::new(PitonSession::new(client)));
186	        self.set_completions(self.lsp.clone(), cx);
187	    }
188	
189	    fn set_completions(&mut self, lsp: Option<Arc<PitonSession>>, cx: &mut Context<Self>) {
190	        let completions = Rc::new(PromptCompletions { lsp });
191	        self.editor.update(cx, |editor, _| {
192	            editor.lsp_mut().completion_provider = Some(completions)
193	        });
194	    }
195	
196	    fn submit(&mut self, window: &mut Window, cx: &mut Context<Self>) {
197	        let text = self.editor.read(cx).value().to_string();
198	        if text.is_empty() {
199	            return;
200	        }
201	        self.editor
202	            .update(cx, |editor, cx| editor.set_value("", window, cx));
203	        cx.emit(Submit {
204	            text,
205	            mode: TABS[self.selected_tab],
206	        });
207	    }
208	
209	    /// Esc closes an open completion menu, and otherwise takes focus out of
210	    /// the input.
211	    fn escape(&mut self, window: &mut Window, cx: &mut Context<Self>) {
212	        if self.editor.read(cx).completion_menu_state().open {
213	            self.editor.update(cx, |editor, cx| {
214	                editor.route_overlay_action(Box::new(Escape), window, cx)
215	            });
216	        } else {
217	            self.focus_handle.focus(window, cx);
218	        }
219	    }
220	
221	    /// The rows `text` takes in the editor: one per line, plus one for every
222	    /// soft wrap, wrapped the way the editor wraps it.
223	    fn visual_rows(&self, text: &str, window: &Window, cx: &App) -> usize {
224	        let Some(wrap_width) = self.text_width.map(|width| width - WRAP_RIGHT_MARGIN) else {
225	            return text.split('\n').count();
226	        };
227	        let theme = cx.theme();
228	        let mut wrapper = window
229	            .text_system()
230	            .line_wrapper(font(theme.mono_font_family.clone()), theme.mono_font_size);
231	        text.split('\n')
232	            .map(|line| {
233	                1 + wrapper
234	                    .wrap_line(&[LineFragment::text(line)], wrap_width)
235	                    .count()
236	            })
237	            .sum()
238	    }
239	}
240	
241	impl Render for ChatInput {
242	    fn render(&mut self, window: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
243	        let text = self.editor.read(cx).value();
244	        let rows = self.visual_rows(&text, window, cx).clamp(1, MAX_ROWS);
245	        // Fit the text with the editor's own metrics: its laid-out line height
246	        // plus the padding and border around its rows. Until the editor has
247	        // painted, the border is estimated at a device pixel or more per side.
248	        let line_height = self
249	            .editor
250	            .read(cx)
251	            .line_height()
252	            .unwrap_or_else(|| window.line_height());
253	        let chrome = self.chrome.unwrap_or_else(|| {
254	            gpui_kit::component::Size::Medium.input_py() * 2.
255	                + ceil_to_device_pixel(px(1.), window) * 2.
256	        });
257	        let height = ceil_to_device_pixel(line_height * rows as f32 + chrome, window);
258	        let one_row = ceil_to_device_pixel(line_height + chrome, window);
259	        let empty = text.is_empty();
260	
261	        // Once the editor has painted, check how it was laid out: the width
262	        // its text wrapped in (a resized window wraps long lines differently)
263	        // and the padding and border around its rows. When either changed,
264	        // the input re-fits.
265	        let this = cx.entity().downgrade();
266	        let editor = self.editor.clone();
267	        let track_layout = canvas(
268	            |_, _, _| {},
269	            move |bounds, _, _, cx| {
270	                let Some(text_bounds) = editor.read(cx).text_bounds() else {
271	                    return;
272	                };
273	                let width = text_bounds.size.width;
274	                let chrome = bounds.size.height - text_bounds.size.height;
275	                this.update(cx, |this, cx| {
276	                    let chrome_changed = this
277	                        .chrome
278	                        .is_none_or(|old| (old - chrome).abs() > px(0.01));
279	                    if this.text_width != Some(width) || chrome_changed {
280	                        this.text_width = Some(width);
281	                        if chrome_changed {
282	                            this.chrome = Some(chrome);
283	                        }
284	                        cx.notify();
285	                    }
286	                })
287	                .ok();
288	            },
289	        )
290	        .absolute()
291	        .size_full();
292	
293	        let chat_input = cx.entity().downgrade();
294	        let tabs = TabBar::new("chat-tabs")
295	            .selected_index(self.selected_tab)
296	            .on_click(move |ix, window, cx| {
297	                chat_input
298	                    .update(cx, |this, cx| {
299	                        this.selected_tab = *ix;
300	                        this.focus(window, cx);
301	                        cx.notify();
302	                    })
303	                    .ok();
304	            })
305	            .children(TABS.map(|mode| Tab::new().label(mode.label())));
306	
307	        let body = div().flex().flex_row().items_end().gap_2().p_3();
308	
309	        div()
310	            .track_focus(&self.focus_handle)
311	            .flex()
312	            .flex_col()
313	            .border_t_1()
314	            .border_color(cx.theme().border)
315	            .capture_action(cx.listener(|this, _: &IndentInline, _, cx| {
316	                // Tab cycles the tabs rather than indenting, and the input
317	                // keeps focus. An open completion menu keeps its own Tab.
318	                if !this.editor.read(cx).completion_menu_state().open {
319	                    cx.stop_propagation();
320	                    this.selected_tab = (this.selected_tab + 1) % TABS.len();
321	                    cx.notify();
322	                }
323	            }))
324	            // Esc arrives as the window's FocusChat, which matches ahead of the
325	            // editor's own binding, or as the editor's Escape once it has
326	            // nothing to cancel. Handled here, neither reaches the window,
327	            // which would focus the input again.
328	            .on_action(cx.listener(|this, _: &FocusChat, window, cx| this.escape(window, cx)))
329	            .on_action(cx.listener(|this, _: &Escape, window, cx| this.escape(window, cx)))
330	            .capture_action(cx.listener(|this, action: &Enter, window, cx| {
331	                // Catch Ctrl/Cmd+Enter before the editor turns it into a newline.
332	                if action.secondary {
333	                    cx.stop_propagation();
334	                    this.submit(window, cx);
335	                } else if this.editor.read(cx).completion_menu_state().open {
336	                    // gpui-kit's completion menu accepts on Enter but lets the
337	                    // keystroke carry on, which also types a newline: hand the
338	                    // Enter to the menu here and stop it once the menu takes it.
339	                    let action = action.clone();
340	                    let accepted = this.editor.update(cx, |editor, cx| {
341	                        editor.route_overlay_action(Box::new(action), window, cx)
342	                    });
343	                    if accepted {
344	                        cx.stop_propagation();
345	                    }
346	                }
347	            }))
348	            .child(tabs)
349	            .child(
350	                body.child(gpui_kit::TestSupportExt::test_support(
351	                    div()
352	                        .id("prompt-editor")
353	                        .relative()
354	                        .flex_1()
355	                        .min_w_0()
356	                        .child(Editor::new(&self.editor).h(height))
357	                        .child(track_layout),
358	                ))
359	                .child(
360	                    Button::new("send")
361	                        .primary()
362	                        // While the harness works, sending queues the prompt.
363	                        .label(if self.busy { "Queue" } else { "Send" })
364	                        // As tall as the input's single line, so the two line up.
365	                        .h(one_row)
366	                        .tooltip(if self.busy {
367	                            format!("Queue until the harness is free ({SEND_SHORTCUT})")
368	                        } else {
369	                            format!("Send ({SEND_SHORTCUT})")
370	                        })
371	                        .disabled(empty)
372	                        .on_click(cx.listener(|this, _, window, cx| this.submit(window, cx))),
373	                ),
374	            )
375	    }
