378	/// Completions for the chat input: harness mentions after `/` or `@`, and
379	/// Piton from `piton lsp`, when it is running, everywhere else.
380	struct PromptCompletions {
381	    lsp: Option<Arc<PitonSession>>,
382	}
383	
384	impl CompletionProvider for PromptCompletions {
385	    fn completions(
386	        &self,
387	        text: &Rope,
388	        offset: usize,
389	        _: CompletionContext,
390	        _: &mut Window,
391	        cx: &mut App,
392	    ) -> Task<Result<CompletionResponse>> {
393	        let lsp = self.lsp.clone();
394	        let prompt = text.to_string();
395	        let project_dir = ProjectDirectory::get(cx);
396	        cx.background_spawn(async move {
397	            if harness_mentions::mention_at(&prompt, offset).is_some() {
398	                let invocables = harness_mentions::discover(project_dir.as_deref());
399	                let items = harness_mentions::complete(&prompt, offset, &invocables);
400	                return Ok(CompletionResponse::Array(items.unwrap_or_default()));
401	            }
402	            // A slash or hyphen only triggers completion inside a mention.
403	            let typed = prompt
404	                .get(..offset)
405	                .and_then(|before| before.chars().next_back());
406	            match lsp {
407	                Some(lsp) if !matches!(typed, Some('/' | '-')) => lsp.complete(&prompt, offset),
408	                _ => Ok(CompletionResponse::Array(Vec::new())),
409	            }
410	        })
411	    }
412	
413	    fn is_completion_trigger(&self, _: usize, new_text: &str, _: &mut App) -> bool {
414	        new_text.chars().last().is_some_and(|c| {
415	            c.is_alphanumeric() || matches!(c, '{' | '.' | '$' | '@' | ':' | '_' | '/' | '-')
416	        })
417	    }
418	}
