728	    /// What one painted frame of the input looked like.
729	    #[derive(Debug, Clone, Copy)]
730	    struct Frame {
731	        rows: usize,
732	        top: gpui_kit::Pixels,
733	        bottom: gpui_kit::Pixels,
734	        height: gpui_kit::Pixels,
735	        /// The offset the text was painted at in this frame.
736	        painted_scroll_y: gpui_kit::Pixels,
737	        /// The offset the editor kept after painting.
738	        scroll_y: gpui_kit::Pixels,
739	        cursor_top: gpui_kit::Pixels,
740	        cursor_bottom: gpui_kit::Pixels,
741	    }
