743	    /// Presses Enter in the input at the bottom of the window, `presses`
744	    /// times, and records every frame drawn after each press, the way the
745	    /// window draws them: only what the press invalidated, with no forced
746	    /// refresh in between.
747	    async fn frames_after_enter(
748	        presses: usize,
749	        scale_factor: f32,
750	        cx: &mut TestAppContext,
751	    ) -> (gpui_kit::Pixels, Vec<Vec<Frame>>) {
752	        cx.update(|cx| {
753	            gpui_kit::init(cx);
754	            piton_syntax::init();
755	            ProjectDirectory::init(cx);
756	        });
757	        let mut chat_input = None;
758	        let painted = Rc::new(Cell::new(gpui_kit::px(0.)));
759	        let window = cx.add_window(|window, cx| {
760	            let input = cx.new(|cx| ChatInput::new(window, cx));
761	            chat_input = Some(input.clone());
762	            let painted_scroll_y = painted.clone();
763	            let view = cx.new(|_| Probed {
764	                input,
765	                painted_scroll_y,
766	            });
767	            Root::new(view, window, cx)
768	        });
769	        let chat_input = chat_input.unwrap();
770	        let editor = chat_input.read_with(cx, |input, _| input.editor.clone());
771	        let handle = window.into();
772	        // Most displays are not 2x: at other scales the rows are a fraction
773	        // of a pixel off the device grid.
774	        cx.simulate_window_scale_factor_change(handle, scale_factor);
775	        cx.wait_for(handle, TIMEOUT, |_, cx| {
776	            editor.read(cx).line_height().is_some()
777	        })
778	        .await;
779	
780	        let record = |window: &mut Window, cx: &mut gpui_kit::App| {
781	            window.draw(cx).clear(cx);
782	            let bounds = window.find("prompt-editor").bounds();
783	            let editor = editor.read(cx);
784	            let scroll_y = editor.scroll_offset().y;
785	            // The cursor is laid out in window coordinates, before scrolling.
786	            let (cursor, _) = editor.cursor_layout().unwrap();
787	            let painted_scroll_y = painted.get();
788	            Frame {
789	                rows: editor.value().split('\n').count(),
790	                top: bounds.top(),
791	                bottom: bounds.bottom(),
792	                height: bounds.size.height,
793	                painted_scroll_y,
794	                scroll_y,
795	                cursor_top: cursor.top() + painted_scroll_y,
796	                cursor_bottom: cursor.bottom() + painted_scroll_y,
797	            }
798	        };
799	
800	        cx.update_window(handle, |_, window, cx| {
801	            editor.read(cx).focus_handle(cx).focus(window, cx);
802	            window.render_frame(cx);
803	            window.render_frame(cx);
804	            window.input("x", cx);
805	        })
806	        .unwrap();
807	        let line_height = editor.read_with(cx, |editor, _| editor.line_height().unwrap());
808	
809	        let mut presses_frames = vec![];
810	        for _ in 0..presses {
811	            let frames = cx
812	                .update_window(handle, |_, window, cx| {
813	                    let before = record(window, cx);
814	                    window.dispatch_keystroke(gpui_kit::Keystroke::parse("enter").unwrap(), cx);
815	                    let mut frames = vec![before];
816	                    for _ in 0..6 {
817	                        frames.push(record(window, cx));
818	                    }
819	                    frames
820	                })
821	                .unwrap();
822	            cx.run_until_parked();
823	            presses_frames.push(frames);
824	        }
825	        (line_height, presses_frames)
826	    }
