828	    /// Enter grows the input by one row in the very next frame, and it stays
829	    /// put from then on: the bottom edge never moves, the first line never
830	    /// scrolls out of view, and the cursor is always inside the input.
831	    async fn assert_enter_grows_without_flicker(scale_factor: f32, cx: &mut TestAppContext) {
832	        let (line_height, presses) = frames_after_enter(MAX_ROWS + 3, scale_factor, cx).await;
833	        let bottom = presses[0][0].bottom;
834	        let one_row = presses[0][0].height;
835	        for (press, frames) in presses.iter().enumerate() {
836	            let rows = frames.last().unwrap().rows;
837	            let expected = one_row + line_height * (rows.min(MAX_ROWS) - 1) as f32;
838	            for (ix, frame) in frames.iter().enumerate().skip(1) {
839	                let context = format!(
840	                    "at {scale_factor}x, line height {line_height:?}, press {press}, frame {ix} of {frames:#?}"
841	                );
842	                assert!(
843	                    (frame.height - expected).abs() <= gpui_kit::px(0.5),
844	                    "height is not {expected:?} rows: {context}"
845	                );
846	                assert!(
847	                    (frame.bottom - bottom).abs() <= gpui_kit::px(0.5),
848	                    "the bottom edge moved from {bottom:?}: {context}"
849	                );
850	                if rows <= MAX_ROWS {
851	                    assert!(
852	                        frame.painted_scroll_y.abs() <= gpui_kit::px(0.5),
853	                        "painted scrolled although everything fits: {context}"
854	                    );
855	                } else {
856	                    assert!(
857	                        (frame.painted_scroll_y - frames.last().unwrap().painted_scroll_y).abs()
858	                            <= gpui_kit::px(0.5),
859	                        "scroll did not settle in the first frame: {context}"
860	                    );
861	                }
862	                assert!(
863	                    frame.cursor_top >= frame.top - gpui_kit::px(0.5)
864	                        && frame.cursor_bottom <= frame.bottom + gpui_kit::px(0.5),
865	                    "the cursor is outside the input: {context}"
866	                );
867	            }
868	        }
869	    }
870	
871	    #[gpui_kit::test]
872	    async fn enter_grows_the_input_without_flicker_at_1x(cx: &mut TestAppContext) {
873	        assert_enter_grows_without_flicker(1.0, cx).await;
