617	    #[gpui::test]
618	    fn group_callback_overrides_child_callback(cx: &mut TestAppContext) {
619	        let (cx, child_clicks, group_clicks) = harness(cx, true, false);
620	        let position = cx.debug_bounds("first-tab").unwrap().center();
