663	        let prefix = cx.debug_bounds("tab-prefix").unwrap();
664	        let child = cx.debug_bounds("tab-child").unwrap();
665	        let suffix = cx.debug_bounds("tab-suffix").unwrap();
666	        assert!(prefix.origin.x < child.origin.x);
