/// The tabs the input sits in, in the order Tab cycles them.
const TABS: [SendMode; 3] = [SendMode::Code, SendMode::Both, SendMode::Spec];

/// The side of the square + tab, a little under the height of the tabs.
const BOTH_TAB_SIZE: Pixels = px(26.);

/// What a prompt is sent to work on: the selected tab.
#[derive(Clone, Copy, Debug, PartialEq)]
pub enum SendMode {
    Code,
    /// The code and the spec together.
    Both,
    Spec,
}

impl SendMode {
    fn label(self) -> &'static str {
        match self {
            SendMode::Code => "Code",
            SendMode::Both => "Code and Spec",
            SendMode::Spec => "Spec",
        }
    }

    fn tab(self) -> Tab {
        match self {
            // A half tab: a square + icon, sitting on the bottom of the bar
            // like the full tabs either side of it. The tab keeps its own
            // height, so a max height is what shortens it.
            SendMode::Both => Tab::new()
                .icon(Icon::new(IconName::Plus))
                .aria_label(self.label())
                .w(BOTH_TAB_SIZE)
                .max_h(BOTH_TAB_SIZE)
                .self_end(),
            _ => Tab::new().label(self.label()),
        }
    }
}

