    }

    /// Tab in the input moves to the next tab, + then Spec then back to Code,
    /// without indenting the text or taking focus out of the input.
    #[gpui_kit::test]
    async fn tab_cycles_the_tabs_and_keeps_focus(cx: &mut TestAppContext) {
        cx.update(|cx| {
            gpui_kit::init(cx);
