        cx.wait_for(handle, TIMEOUT, |_, cx| {
            let menu = editor.read(cx).completion_menu_state();
            menu.open
                && menu
                    .items
                    .first()
                    .is_some_and(|item| item.label == "ApplicationScope")
        })
        .await;
        let labels: Vec<String> = editor.read_with(cx, |editor, _| {
            editor
                .completion_menu_state()
                .items
